create extension if not exists pg_cron;
create extension if not exists pg_net;
grant usage on schema private to service_role;
create table if not exists private.backup_runs(id uuid primary key default gen_random_uuid(),day date not null unique,state text not null default'pending'check(state in('pending','running','completed','failed')),document jsonb not null,plan jsonb,media jsonb not null default'{}',cursor integer not null default 0,lease uuid,lease_until timestamptz,attempts integer not null default 0,manifest_path text,error_code text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists private.notification_outbox(id bigint generated by default as identity primary key,dedupe_key text unique not null,payload jsonb not null,attempts integer not null default 0,next_attempt_at timestamptz not null default now(),delivered_at timestamptz,last_status text,lease_until timestamptz,created_at timestamptz not null default now());
create table if not exists private.alert_states(key text primary key,active boolean not null);
alter table private.backup_runs enable row level security;alter table private.notification_outbox enable row level security;alter table private.alert_states enable row level security;
revoke all on private.backup_runs,private.notification_outbox,private.alert_states from public,anon,authenticated;
create index if not exists outbox_pending_idx on private.notification_outbox(next_attempt_at)where delivered_at is null;
select vault.create_secret(replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),'wj_maintenance_token','Internal maintenance endpoint authentication')where not exists(select 1 from vault.secrets where name='wj_maintenance_token');
insert into public.app_settings(key,value)values('jobs','{"backup_enabled":true,"backup_hour":3,"report_hour":9,"analytics_enabled":true,"discord_enabled":false,"retention_days":30}')on conflict(key)do nothing;

create or replace function private.prepare_daily_jobs()returns void language plpgsql security definer set search_path=''as $$
declare d date:=(now()at time zone'Asia/Taipei')::date;hour_value int:=extract(hour from now()at time zone'Asia/Taipei');config jsonb;document jsonb;report jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('wj_daily_jobs',0));select value into config from public.app_settings where key='jobs';
 if coalesce((config->>'backup_enabled')::boolean,true)and hour_value>=coalesce((config->>'backup_hour')::int,3)and not exists(select 1 from private.backup_runs where day=d)then
  document:=private.system_backup_document();
  if octet_length(document::text)>16777216 then
   insert into private.backup_runs(day,state,document,error_code,attempts)values(d,'failed','{}','DOCUMENT_SIZE_LIMIT',5);
  else
   insert into private.backup_runs(day,document)values(d,document);
   insert into private.app_saved_backups(actor_user_id,label,document)values(null,'每日自動資料快照（完整圖片另存）',document);
  end if;
 end if;
 if coalesce((config->>'discord_enabled')::boolean,false)and hour_value>=coalesce((config->>'report_hour')::int,9)then
  report:=private.analytics_report(d-1,d-1);
  insert into private.notification_outbox(dedupe_key,payload)values('daily:'||(d-1)::text,jsonb_build_object('type','daily','day',d-1,'analytics',report,'tasks',jsonb_build_object('pending_orders',(select count(*)from public.orders where status in('pending_review','paid_awaiting_purchase','arrived_for_check','refund_pending')),'low_stock',(select count(*)from public.products p join public.inventory_balances b on b.product_id=p.id where p.publication_status<>'archived'and b.quantity_on_hand<=p.low_stock_threshold))))on conflict(dedupe_key)do nothing;
 end if;
 delete from private.analytics_event_keys where created_at<now()-interval'30 days';delete from private.analytics_visitors where day<d-29;delete from private.analytics_counts where day<d-29;delete from private.analytics_limits where expires_at<now();
end $$;
revoke all on function private.prepare_daily_jobs()from public,anon,authenticated;

create or replace function private.queue_business_notice()returns trigger language plpgsql security definer set search_path=''as $$
declare code text;label text;was_active boolean;active_now boolean;begin
 if current_setting('wj.restoring',true)='true'or not coalesce((select(value->>'discord_enabled')::boolean from public.app_settings where key='jobs'),false)then return new;end if;
 if tg_table_name='orders'then
  if tg_op='INSERT'then code:='new_order';elsif new.status='refund_pending'and old.status is distinct from new.status then code:='refund_task';else return new;end if;
  insert into private.notification_outbox(dedupe_key,payload)values(code||':'||new.id::text||':'||new.updated_at::text,jsonb_build_object('type',code,'order_number',new.order_number::text))on conflict(dedupe_key)do nothing;
 else
  select p.name_zh,new.quantity_on_hand<=p.low_stock_threshold into label,active_now from public.products p where p.id=new.product_id and p.publication_status<>'archived';
  if label is null then return new;end if;
  select active into was_active from private.alert_states where key='stock:'||new.product_id::text for update;
  insert into private.alert_states(key,active)values('stock:'||new.product_id::text,active_now)on conflict(key)do update set active=excluded.active;
  if active_now is distinct from coalesce(was_active,false)then insert into private.notification_outbox(dedupe_key,payload)values('stock:'||new.product_id::text||':'||clock_timestamp()::text,jsonb_build_object('type',case when active_now then'low_stock'else'stock_recovered'end,'product',left(label,100)))on conflict(dedupe_key)do nothing;end if;
 end if;return new;
end $$;
create trigger order_operational_notice after insert or update on public.orders for each row execute function private.queue_business_notice();
create trigger stock_operational_notice after insert or update on public.inventory_balances for each row execute function private.queue_business_notice();
revoke all on function private.queue_business_notice()from public,anon,authenticated;

create or replace function private.maintenance_work(p_token text,p_action text,p_payload jsonb default'{}')returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare expected text;job private.backup_runs;config jsonb;hook text;notifications jsonb;lease_id uuid;expired jsonb;keep jsonb;begin
 select decrypted_secret into expected from vault.decrypted_secrets where name='wj_maintenance_token'limit 1;
 if expected is null or p_token is null or p_token<>expected then raise insufficient_privilege using message='Invalid maintenance authentication';end if;
 if p_action='claim'then
  perform private.prepare_daily_jobs();select value into config from public.app_settings where key='jobs';
  select *into job from private.backup_runs where state in('pending','running','failed')and attempts<5 and coalesce(lease_until,'-infinity')<now()order by day for update skip locked limit 1;
  if found then lease_id:=gen_random_uuid();update private.backup_runs set state='running',lease=lease_id,lease_until=now()+interval'2 minutes',attempts=attempts where id=job.id;end if;
  if coalesce((config->>'discord_enabled')::boolean,false)then
   select decrypted_secret into hook from vault.decrypted_secrets where name='wj_discord_webhook'limit 1;
   if hook is not null then
    with picked as(select id from private.notification_outbox where delivered_at is null and attempts<3 and next_attempt_at<=now()and coalesce(lease_until,'-infinity')<now()order by id for update skip locked limit 10),claimed as(update private.notification_outbox n set lease_until=now()+interval'2 minutes'from picked p where n.id=p.id returning n.*)select coalesce(jsonb_agg(jsonb_build_object('id',id::text,'payload',payload)),'[]')into notifications from claimed;
   end if;
  end if;
  return jsonb_build_object('backup',case when lease_id is not null then jsonb_build_object('id',job.id,'day',job.day,'lease',lease_id,'document',job.document,'plan',job.plan,'media',job.media,'cursor',job.cursor)end,'notifications',coalesce(notifications,'[]'),'webhook',hook,'retention_days',30);
 elsif p_action in('progress','complete','fail')then
  select *into job from private.backup_runs where id=(p_payload->>'id')::uuid and lease=(p_payload->>'lease')::uuid for update;if not found then raise sqlstate'PT409'using message='Maintenance lease changed';end if;
  if p_action='progress'then
   update private.backup_runs set plan=coalesce(p_payload->'plan',plan),media=media||coalesce(p_payload->'media','{}'),cursor=greatest(cursor,coalesce((p_payload->>'cursor')::int,cursor)),state=case when coalesce((p_payload->>'release')::boolean,false)then'pending'else'running'end,lease_until=case when coalesce((p_payload->>'release')::boolean,false)then now()-interval'1 second'else now()+interval'2 minutes'end where id=job.id;
  elsif p_action='complete'then
   if coalesce((p_payload->>'object_count')::int,-1)<>jsonb_array_length(job.plan)or (select count(*)from jsonb_object_keys(job.media))<>jsonb_array_length(job.plan)then raise check_violation using message='Backup manifest is incomplete';end if;
   update private.backup_runs set state='completed',completed_at=clock_timestamp(),manifest_path=p_payload->>'manifest_path',lease_until=null,error_code=null where id=job.id;
  else
   update private.backup_runs set state='failed',attempts=attempts+1,error_code=left(coalesce(p_payload->>'code','BACKUP_FAILED'),80),lease_until=now()+interval'15 minutes'where id=job.id;
   insert into private.notification_outbox(dedupe_key,payload)values('backup_fail:'||job.id::text,jsonb_build_object('type','system_alert','code','BACKUP_FAILED','day',job.day))on conflict(dedupe_key)do nothing;
  end if;return jsonb_build_object('saved',true);
 elsif p_action='notification_result'then
  update private.notification_outbox set attempts=attempts+1,last_status=left(p_payload->>'status',40),delivered_at=case when p_payload->>'status'='delivered'then now()else null end,next_attempt_at=now()+interval'30 minutes',lease_until=null where id=(p_payload->>'id')::bigint;
  return jsonb_build_object('saved',true);
 elsif p_action='retention'then
  select coalesce(jsonb_agg(manifest_path)filter(where manifest_path is not null),'[]')into expired from private.backup_runs where day<(now()at time zone'Asia/Taipei')::date-29;
  delete from private.backup_runs where day<(now()at time zone'Asia/Taipei')::date-29;
  delete from private.app_saved_backups where created_at<now()-interval'30 days';
  delete from private.notification_outbox where created_at<now()-interval'30 days';
  select coalesce(jsonb_agg(distinct j.value->>'backup_path'),'[]')into keep from private.backup_runs r cross join lateral jsonb_each(r.media)j;
  return jsonb_build_object('expired_manifests',expired,'keep_media',keep);
 end if;raise invalid_parameter_value;
end $$;
create or replace function public.maintenance_work(p_token text,p_action text,p_payload jsonb default'{}')returns jsonb language sql set search_path=''as $$select private.maintenance_work(p_token,p_action,p_payload);$$;
revoke all on function private.maintenance_work(text,text,jsonb),public.maintenance_work(text,text,jsonb)from public,anon,authenticated;
grant execute on function private.maintenance_work(text,text,jsonb),public.maintenance_work(text,text,jsonb)to service_role;

create or replace function private.admin_job_control(p_action text,p_payload jsonb default'{}')returns jsonb language plpgsql security definer set search_path=''as $$
declare config jsonb;old_config jsonb;ver timestamptz;hook text;secret_id uuid;begin
 if auth.uid()is null or not private.is_store_admin()then raise insufficient_privilege;end if;
 if p_action='status'then return jsonb_build_object('config',(select value from public.app_settings where key='jobs'),'updated_at',(select updated_at from public.app_settings where key='jobs'),'webhook_configured',exists(select 1 from vault.secrets where name='wj_discord_webhook'),'backups',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'day',b.day,'state',b.state,'cursor',b.cursor,'objects',coalesce(jsonb_array_length(b.plan),0),'error_code',b.error_code,'completed_at',b.completed_at)order by b.day desc),'[]')from(select *from private.backup_runs order by day desc limit 30)b),'failed_notifications',(select count(*)from private.notification_outbox where delivered_at is null and attempts>=3),'pending_notifications',(select count(*)from private.notification_outbox where delivered_at is null and attempts<3));
 elsif p_action='backup_get'then return(select jsonb_build_object('manifest_path',manifest_path)from private.backup_runs where id=(p_payload->>'id')::uuid and state='completed');
 elsif p_action='save'then
  select value,updated_at into old_config,ver from public.app_settings where key='jobs'for update;
  if ver is distinct from(p_payload->>'expected_updated_at')::timestamptz then raise sqlstate'PT409'using message='Schedule settings changed on another device';end if;
  config:=p_payload->'config';if jsonb_typeof(config->'backup_enabled')is distinct from'boolean'or jsonb_typeof(config->'analytics_enabled')is distinct from'boolean'or jsonb_typeof(config->'discord_enabled')is distinct from'boolean'or config->>'backup_hour'is null or config->>'report_hour'is null or (config->>'backup_hour')::int not between 0 and 23 or(config->>'report_hour')::int not between 0 and 23 then raise check_violation using message='Invalid schedule settings';end if;
  if p_payload?'webhook'then
   hook:=btrim(p_payload->>'webhook');if hook!~'^https://discord\.com/api/webhooks/[0-9]+/[A-Za-z0-9_-]+$'or length(hook)>500 then raise check_violation using message='Use an official Discord webhook URL';end if;
   select id into secret_id from vault.secrets where name='wj_discord_webhook'limit 1;
   if secret_id is null then perform vault.create_secret(hook,'wj_discord_webhook');else perform vault.update_secret(secret_id,hook);end if;
  end if;
  if(config->>'discord_enabled')::boolean and not exists(select 1 from vault.secrets where name='wj_discord_webhook')then raise check_violation using message='Configure your Discord channel webhook first';end if;
  select value into old_config from public.app_settings where key='jobs'for update;
  config:=jsonb_build_object('backup_enabled',(config->>'backup_enabled')::boolean,'analytics_enabled',(config->>'analytics_enabled')::boolean,'discord_enabled',(config->>'discord_enabled')::boolean,'backup_hour',(config->>'backup_hour')::int,'report_hour',(config->>'report_hour')::int,'retention_days',30);
  update public.app_settings set value=config,updated_by=auth.uid(),updated_at=clock_timestamp()where key='jobs';
  insert into public.audit_logs(actor_user_id,entity_type,entity_id,action,before_data,after_data)values(auth.uid(),'settings','jobs','schedule_settings_updated',old_config,config);return jsonb_build_object('saved',true);
 elsif p_action='retry_backup'then
  update private.backup_runs set state='pending',attempts=0,lease_until=null,error_code=null where id=(p_payload->>'id')::uuid and state='failed';return jsonb_build_object('saved',found);
 end if;raise invalid_parameter_value;
end $$;
create or replace function public.admin_job_control(p_action text,p_payload jsonb default'{}')returns jsonb language sql set search_path=''as $$select private.admin_job_control(p_action,p_payload);$$;
revoke all on function private.admin_job_control(text,jsonb),public.admin_job_control(text,jsonb)from public,anon;
grant execute on function private.admin_job_control(text,jsonb),public.admin_job_control(text,jsonb)to authenticated;

create or replace function private.kick_maintenance()returns bigint language plpgsql security definer set search_path=''as $$
declare token text;request_id bigint;begin
 perform private.prepare_daily_jobs();select decrypted_secret into token from vault.decrypted_secrets where name='wj_maintenance_token'limit 1;
 select net.http_post(url:='https://wlrwlqchlxehlvkyesnj.supabase.co/functions/v1/store-maintenance',headers:=jsonb_build_object('Content-Type','application/json','x-maintenance-token',token),body:='{}'::jsonb,timeout_milliseconds:=60000)into request_id;return request_id;
end $$;
revoke all on function private.kick_maintenance()from public,anon,authenticated;
select cron.schedule('wu-jacky-maintenance','*/15 * * * *','select private.kick_maintenance()');

create policy backup_admin_read on storage.objects for select to authenticated using(bucket_id='app-backups'and private.is_store_admin());
